#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_INPUT 0x400
#define OUT_BUF (MAX_INPUT+1)

int main(int argc, char *argv[]) {
    const char *src;
    size_t len, i, out = 0;
    char outbuf[OUT_BUF];
    bool pending_space = false;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    src = argv[1];
    len = strlen(src);
    if (len > MAX_INPUT) len = MAX_INPUT;
    for (i = 0; i < len; ++i) {
        char c = src[i];
        bool is_ws = (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
        if (is_ws) {
            if (out > 0) pending_space = true;
        } else {
            if (pending_space) {
                outbuf[out++] = ' ';
                pending_space = false;
            }
            outbuf[out++] = c;
        }
    }
    outbuf[out] = '\0';
    if (out == 0) puts("EMPTY"); else puts(outbuf);
    return 0;
}
